<div class="sf-container sf-page-y"><div class="mx-auto max-w-md"><header class="text-center"><p class="sf-eyebrow">Account recovery</p><h1 class="mt-2 text-3xl font-semibold tracking-tight">Reset your password</h1><p class="mt-3 text-slate-600 dark:text-slate-300">Enter your email and we’ll send reset instructions if an account exists.</p></header><div class="sf-card mt-8" aria-live="polite">@if($sent)<div class="sf-callout sf-callout-info">If that email exists, we sent a reset link.</div><a href="{{ url('/account/login') }}" wire:navigate class="sf-button sf-button-secondary mt-5 w-full">Back to login</a>@else<form wire:submit="sendResetLink"><label for="forgot-email" class="sf-label">Email address</label><input id="forgot-email" name="email" type="email" wire:model="email" autocomplete="email" required autofocus class="sf-input mt-1 w-full @error('email') sf-input-error @enderror">@error('email')<p class="sf-field-error">{{ $message }}</p>@enderror<button class="sf-button sf-button-primary mt-5 w-full" wire:loading.attr="disabled" wire:target="sendResetLink">Email reset link</button></form>@endif</div></div></div>
